 "content": "def transform(grid):
    """Complete 2x2 groups of panels by horizontal/vertical reflection."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row if v != 0}
    # ARC panel dividers are full straight lines in a single non-background color.
    sep = None
    for color in colors:
        if any(all(v == color for v in row) for row in g) or any(all(g[r][c] == color for r in range(h)) for c in range(w)):
            sep = color
            break
    if sep is None:
        return g
    hr = [r for r, row in enumerate(g) if all(v == sep for v in row)]
    vc = [c for c in range(w) if all(g[r][c] == sep for r in range(h))]
    rb = [-1] + hr + [h]
    cb = [-1] + vc + [w]
    tiles = [[ [g[r][c] for c in range(cb[j]+1, cb[j+1])] for r in range(rb[i]+1, rb[i+1])] for i in range(len(rb)-1) for j in []] # unused
    nr, nc = len(rb)-1, len(cb)-1
    cells = [[ [g[r][c] for c in range(cb[j]+1, cb[j+1])] for r in range(rb[i]+1, rb[i+1])] for i in range(nr) for j in []]
    # Keep cell matrices in a rectangular index map.
    cells = []
    for i in range(nr):
        rowcells=[]
        for j in range(nc):
            rowcells.append([row[cb[j]+1:cb[j+1]] for row in g[rb[i]+1:rb[i+1]]])
        cells.append(rowcells)

    def flip_x(a):
        return [row[::-1] for row in a]
    def flip_y(a):
        return a[::-1]
    def nonzero(a):
        return any(v != 0 and v != sep for row in a for v in row)
    def color_of(a):
        return {v for row in a for v in row if v not in (0, sep)}
    def transformed(a, y, x):
        b = [row[:] for row in a]
        if x: b = flip_x(b)
        if y: b = flip_y(b)
        return b

    # Solve each 2x2 panel group independently. A tile at (dy,dx) is the
    # base motif reflected dy times vertically and dx times horizontally.
    for i in range(nr-1):
        for j in range(nc-1):
            group = [[cells[i+y][j+x] for x in range(2)] for y in range(2)]
            # The panels in a group must have equal dimensions.
            hh, ww = len(group[0][0]), len(group[0][0][0]) if group[0][0] else 0
            if not hh or not ww or any(len(a) != hh or any(len(row) != ww for row in a) for line in group for a in line):
                continue
            present = [(y,x,group[y][x]) for y in range(2) for x in range(2) if nonzero(group[y][x])]
            if len(present) < 2:
                continue
            palette = set().union(*(color_of(a) for _,_,a in present))
            if len(palette) != 1:
                continue
            best = None
            for y0,x0,seed in present:
                base = transformed(seed, y0, x0)
                matches = [(y,x) for y,x,a in present if a == transformed(base,y,x)]
                if best is None or len(matches) > best[0]:
                    best = (len(matches), base)
            if best is None or best[0] < 2:
                continue
            base = best[1]
            # Only complete a coherent reflection group; preserve existing panels.
            if any(a != transformed(base,y,x) for y,x,a in present):
                continue
            for y in range(2):
                for x in range(2):
                    if not nonzero(group[y][x]):
                        rr0, rr1 = rb[i+y]+1, rb[i+y+1]
                        cc0, cc1 = cb[j+x]+1, cb[j+x+1]
                        expected = transformed(base,y,x)
                        for rr in range(hh):
                            for cc in range(ww):
                                g[rr0+rr][cc0+cc] = expected[rr][cc]
    return g
